/**
 * A preview card shown on hover or focus (`design/components/hover-card.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/hover-card.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/hover-card'
import { normalizeProps } from '@zag-js/solid'

import {
  TOOLTIP_DELAY_MS,
  TOOLTIP_SKIP_DELAY_MS,
  afresh,
  anchorProps,
  claimSlot,
  createDerived,
  devWarning,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/hover-card.module.css'

export type HoverCardSide = NonNullable<HoverCardProps['side']>

export type HoverCardAlign = NonNullable<HoverCardProps['align']>

export interface HoverCardProps {
  align?: 'start' | 'center' | 'end'
  /**
   * The trigger: one focusable element with its own destination or action, which the card
   * previews but never replaces. A HoverCard on an inert span previews nothing reachable.
   */
  children: JSX.Element
  /**
   * Vocabulary content, typically a Stack of Avatar/Text/Badge rows. It has no typed shape,
   * because person, ticket and link previews share no anatomy and the closed vocabulary already
   * constrains it. The never-load-bearing law governs the content, not a slot shape.
   */
  content: JSX.Element
  /**
   * Opens on mount, for galleries and tests; screens wait for the reader to hover.
   */
  defaultOpen?: boolean
  side?: 'bottom' | 'top' | 'right' | 'left'
}

/** A preview card shown on hover or focus. */
export default function HoverCard(given: HoverCardProps): JSX.Element {
  const props = mergeProps(
    { side: 'bottom', align: 'start' } as Defaults<HoverCardProps, 'side' | 'align'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          defaultOpen: props.defaultOpen,
          openDelay: TOOLTIP_DELAY_MS,
          closeDelay: TOOLTIP_SKIP_DELAY_MS,
          positioning: {
            placement: props.align === 'center' ? props.side : `${props.side}-${props.align}`,
            offset: { mainAxis: 4 },
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const present = usePresence(
      () => api.value.open,
      () => panel.value,
    )
    const effect1 = () => {
      devWarning(
        api.value.open &&
          panel.value?.querySelector(
            'a[href], button, input, select, textarea, [tabindex]:not([tabindex="-1"])',
          ) != null,
        'HoverCard: the preview contains interactive content, which keyboard and touch readers can never reach. A card the reader must operate is a Popover.',
      )
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect1,
      true,
    )
    return (
      <>
        {/* trigger */}
        <span {...mergeParts(anchorProps(api.value.getTriggerProps()), { class: styles.anchor })}>
          {props.children}
        </span>
        <Portal>
          {afresh(() => (
            <>
              {present() ? (
                <div {...mergeParts(api.value.getPositionerProps())}>
                  {/* panel */}
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.panel,
                      hidden: undefined,
                      'data-member': 'hover-card',
                    })}
                    ref={panel.attach}
                  >
                    {props.content}
                  </div>
                </div>
              ) : null}
            </>
          ))}
        </Portal>
      </>
    )
  })
}
